   528→  const goBack = useTabStore((state) => state.goBack);
   529→  const goForward = useTabStore((state) => state.goForward);
   530→  const canGoBackFn = useTabStore((state) => state.canGoBack);
   531→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
   532→  const jumpToHistoryStore = useTabStore((state) => state.jumpToHistory);
   533→
   534→  const goBackInTab = useCallback(() => {
   535→    if (activeTabId && canGoBackFn(activeTabId)) {
   536→      goBack(activeTabId);
   537→    }
   538→  }, [activeTabId, canGoBackFn, goBack]);
   539→
   540→  const goForwardInTab = useCallback(() => {
   541→    if (activeTabId && canGoForwardFn(activeTabId)) {
   542→      goForward(activeTabId);
   543→    }
   544→  }, [activeTabId, canGoForwardFn, goForward]);
   545→
   546→  const jumpToHistory = useCallback(
   547→    (historyIndex: number) => {
   548→      if (!activeTabId) return;
   549→      jumpToHistoryStore(activeTabId, historyIndex);
   550→    },
   551→    [activeTabId, jumpToHistoryStore]
   552→  );
   553→
   554→  const navigateInTab = useCallback(
   555→    (url: string) => {
   556→      if (!activeTabId) return;
   557→      navigate(activeTabId, url);
   558→    },
   559→    [activeTabId, navigate]
   560→  );
   561→
   562→  return useMemo(
   563→    () => ({ goBackInTab, goForwardInTab, jumpToHistory, navigateInTab }),
   564→    [goBackInTab, goForwardInTab, jumpToHistory, navigateInTab]
   565→  );
   566→}
