   568→// ─── Composed hook: usePageTabs (backward-compatible) ───────────────────────
   569→// Composes the 4 granular hooks. Existing consumers can continue using this
   570→// without changes, but new code should prefer the granular hooks.
   571→
   572→export function usePageTabs() {
   573→  const tabs = useTabList();
   574→  const activeState = useActiveTabState();
   575→  const actions = useTabActions();
   576→  const navigation = useTabNavigation();
   577→
   578→  return useMemo(
   579→    () => ({
   580→      tabs,
   581→      ...activeState,
   582→      ...actions,
   583→      ...navigation,
   584→    }),
   585→    [tabs, activeState, actions, navigation]
   586→  );
   587→}
