   591→function safeHostname(url: string): string {
   592→  try {
   593→    return new URL(url).hostname;
   594→  } catch {
   595→    return url;
   596→  }
   597→}
   598→
   599→function buildLocationFromLegacyUrl(url: string): DesktopLocation {
   600→  const parsed = urlToLocation(url);
   601→  if (parsed) {
   602→    return parsed;
   603→  }
   604→
   605→  if (url === "/documents") {
   606→    return { kind: "documents" };
   607→  }
   608→  if (url === "/devices/pair") {
   609→    return { kind: "device-pair" };
   610→  }
   611→  if (url.startsWith("/settings")) {
   612→    const section = url.split("/")[2];
   613→    return { kind: "settings", section: normalizeSettingsSection(section) };
   614→  }
   615→
   616→  if (url === "/publish" || url === "/my-packages" || url === "/analytics") {
   617→    return { kind: "global-route", path: url };
   618→  }
   619→
   620→  if (url.startsWith("/workspace/page")) {
   621→    const parsed = new URL(url, "http://desktop.local");
   622→    const workspaceId = parsed.searchParams.get("workspace_id");
   623→    const pagePath = parsed.searchParams.get("page_path");
   624→    return {
   625→      kind: "workspace-page",
   626→      workspaceId: workspaceId ?? "global",
   627→      pageSlug:
   628→        pagePath?.replace(/^pages\//, "").replace(/\/SKILL\.md$/, "") ?? "page",
   629→    };
   630→  }
   631→
   632→  if (url.startsWith("/workspace/")) {
   633→    const parsed = new URL(url, "http://desktop.local");
   634→    const parts = parsed.pathname.split("/").filter(Boolean);
   635→    const workspaceId = parts[1];
   636→    if (!workspaceId) {
   637→      return { kind: "documents" };
   638→    }
   639→
   640→    if (parts.length === 2) {
   641→      return { kind: "workspace-home", workspaceId };
   642→    }
   643→
   644→    if (parts[2] === "apps" && !parts[3]) {
   645→      return { kind: "workspace-apps", workspaceId };
   646→    }
   647→
   648→    if (parts[2] === "page" && parts[3]) {
   649→      return {
   650→        kind: "workspace-page",
   651→        workspaceId,
   652→        pageSlug: parts
   653→          .slice(3)
   654→          .map((part) => decodeURIComponent(part))
   655→          .join("/"),
   656→      };
   657→    }
   658→
   659→    if (parts[2] === "agent" && parts[3]) {
   660→      return {
   661→        kind: "workspace-agent-detail",
   662→        workspaceId,
   663→        agentId: decodeURIComponent(parts[3]),
   664→      };
   665→    }
   666→
   667→    if (parts[2] === "executor" && parts[3]) {
   668→      return {
   669→        kind: "workspace-executor-detail",
   670→        workspaceId,
   671→        executorType: decodeURIComponent(parts[3]),
   672→      };
   673→    }
   674→
   675→    if (parts[2] === "web") {
   676→      return {
   677→        kind: "workspace-web",
   678→        workspaceId,
   679→        url: parsed.searchParams.get("url") ?? "",
   680→        title: parsed.searchParams.get("title") ?? "Web",
   681→        sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined,
   682→        webId: parsed.searchParams.get("web_id") ?? undefined,
   683→      };
   684→    }
   685→
   686→    return {
   687→      kind: "workspace-section",
   688→      workspaceId,
   689→      section: normalizeWorkspaceSection(parts[2] ?? "chat"),
   690→    };
   691→  }
   692→
   693→  return { kind: "global-route", path: url };
   694→}
