   596→export function resolvePageIndexBranch({
   597→  segment,
   598→  workspaceId,
   599→  workspaces,
   600→  pages,
   601→  activeWorkspaceId,
   602→  currentSection,
   603→  currentArea,
   604→  currentPageSlug,
   605→  currentSettingsSection,
   606→  allowGithub,
   607→  buildLabel,
   608→  onSelectWorkspace,
   609→  onSelectSection,
   610→  labelGlobalWorkspace,
   611→}: ResolvePageIndexBranchInput): BreadcrumbDropdownItem[] {
   612→  const descriptorId = resolveSegmentDescriptorId(segment);
   613→  const input: ResolvePageIndexBranchInput = {
   614→    segment,
   615→    workspaceId,
   616→    workspaces,
   617→    pages,
   618→    activeWorkspaceId,
   619→    currentSection,
   620→    currentArea,
   621→    currentPageSlug,
   622→    currentSettingsSection,
   623→    allowGithub,
   624→    buildLabel,
   625→    onSelectWorkspace,
   626→    onSelectSection,
   627→    labelGlobalWorkspace,
   628→  };
   629→
   630→  const rules: BreadcrumbDropdownRule[] = [
   631→    {
   632→      matches: (_input, descriptorId) => descriptorId === "workspace",
   633→      build: (input) =>
   634→        buildRootDropdownItems({
   635→          workspaces: input.workspaces,
   636→          currentArea: input.currentArea,
   637→          activeWorkspaceId: input.activeWorkspaceId,
   638→          currentSection: input.currentSection,
   639→          activeHref: input.segment.href,
   640→          buildLabel: input.buildLabel,
   641→          onSelectWorkspace: input.onSelectWorkspace,
   642→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   643→        }),
   644→    },
   645→    {
   646→      matches: (input, descriptorId) =>
   647→        (descriptorId === "virtual-folder" || descriptorId === "settings") &&
   648→        input.segment.href.startsWith("/settings/") &&
   649→        input.segment.label === getSettingsSectionLabel(),
   650→      build: (input) =>
   651→        buildRootDropdownItems({
   652→          workspaces: input.workspaces,
   653→          currentArea: input.currentArea,
   654→          activeWorkspaceId: input.activeWorkspaceId,
   655→          currentSection: input.currentSection,
   656→          activeHref: input.segment.href,
   657→          buildLabel: input.buildLabel,
   658→          onSelectWorkspace: input.onSelectWorkspace,
   659→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   660→        }),
   661→    },
   662→    {
   663→      matches: (input, descriptorId) =>
   664→        (descriptorId === "virtual-folder" || descriptorId === "workspace-section:apps") &&
   665→        Boolean(input.segment.meta?.workspaceId) &&
   666→        input.segment.href ===
   667→          `/workspace/${encodeURIComponent(input.segment.meta?.workspaceId ?? "")}/apps`,
   668→      build: (input) =>
   669→        buildWorkspaceAppsDropdownItems({
   670→          workspaceId: input.segment.meta?.workspaceId ?? "",
   671→          activeSection: "apps",
   672→          buildLabel: input.buildLabel,
   673→          onSelectSection: input.onSelectSection,
   674→          allowGithub: input.allowGithub,
   675→          pages: input.pages,
   676→          currentPageSlug: input.currentPageSlug,
   677→        }),
   678→    },
   679→    {
   680→      matches: (input, descriptorId) =>
   681→        Boolean(descriptorId?.startsWith("settings")) &&
   682→        input.segment.href.startsWith("/settings/"),
   683→      build: (input) =>
   684→        buildSettingsDropdownItems({
   685→          activeSection:
   686→            input.segment.href.split("/settings/")[1] ||
   687→            input.currentSettingsSection ||
   688→            "general",
   689→          buildLabel: input.buildLabel,
   690→        }),
   691→    },
   692→    {
   693→      matches: (input, descriptorId) =>
   694→        Boolean(descriptorId?.startsWith("workspace-section:")) &&
   695→        Boolean(input.workspaceId ?? input.segment.meta?.workspaceId),
   696→      build: (input) => {
   697→        const section = input.segment.meta?.section ?? input.currentSection ?? "chat";
   698→        return buildWorkspaceSectionDropdownItems(section, {
   699→          workspaceId: input.workspaceId ?? input.segment.meta?.workspaceId ?? "",
   700→          activeSection: section,
   701→          buildLabel: input.buildLabel,
   702→          onSelectSection: input.onSelectSection,
   703→          allowGithub: input.allowGithub,
   704→        });
   705→      },
   706→    },
   707→    {
   708→      matches: (input, descriptorId) =>
   709→        descriptorId === "workspace-page" &&
   710→        Boolean(input.segment.meta?.pageSlug) &&
   711→        Boolean(input.pages?.length),
   712→      build: (input) => {
   713→        const wId = input.workspaceId ?? input.segment.meta?.workspaceId ?? "";
   714→        const currentSlug = input.segment.meta?.pageSlug ?? "";
   715→        // Find parent prefix to get siblings
   716→        const parentPrefix = currentSlug.includes("/")
   717→          ? currentSlug.slice(0, currentSlug.lastIndexOf("/") + 1)
   718→          : "";
   719→        const depth = parentPrefix ? parentPrefix.split("/").filter(Boolean).length + 1 : 1;
   720→
   721→        const siblings = (input.pages ?? []).filter((page) => {
   722→          // Same depth and same parent prefix
   723→          const pageDepth = page.slug.split("/").filter(Boolean).length;
   724→          if (pageDepth !== depth) return false;
   725→          if (parentPrefix) {
   726→            return page.slug.startsWith(parentPrefix);
   727→          }
   728→          return !page.slug.includes("/");
   729→        });
   730→
   731→        return buildDropdownItems(siblings, (page) => ({
   732→          id: `workspace:${wId}:page:${page.slug}`,
   733→          label: page.name,
   734→          href: `/workspace/${encodeURIComponent(wId)}/page/${page.slug
   735→            .split("/")
   736→            .filter(Boolean)
   737→            .map((s) => encodeURIComponent(s))
   738→            .join("/")}`,
   739→          icon: page.icon,
   740→          isActive: page.slug === currentSlug,
   741→          descriptorId: "workspace-page",
   742→          meta: {
   743→            workspaceId: wId,
   744→            pageSlug: page.slug,
   745→          },
   746→        }));
   747→      },
   748→    },
   749→  ];
   750→
   751→  const matchedRule = rules.find((rule) => rule.matches(input, descriptorId));
   752→
   753→  if (matchedRule) {
   754→    return matchedRule.build(input);
   755→  }
   756→
   757→  return [];
   758→}
